//! Vendored DEFLATE and zlib files for `clazel-deflate` (phase-6.md item
//! 6.2): Wuffs' `test/data/romeo.txt*`, `midsummer.txt*`, `pi.txt*` and
//! `test/data/artificial-deflate/*`.
//!
//! The files are binary or plain text, so there is nothing to translate:
//! like the fonts' converter (`fonts.rs`), this checks that each file is the
//! one its `SOURCE.md` names (a `` - `X`: sha256 `…` `` line) and writes a
//! table that embeds it with `include_bytes!`. Nothing about DEFLATE is
//! parsed here: that is the crate's job and the differential test's.

use std::fmt::Write as _;
use std::path::Path;

use sha2::{Digest, Sha256};

use super::fonts::listed_hash;
use super::hash::to_hex;

/// `tests/data/wuffs-deflate/`: Wuffs' `test/data/` streams and their texts.
pub const FILES_MAIN: &[&str] = &[
    "midsummer.txt",
    "midsummer.txt.zlib",
    "pi.txt",
    "pi.txt.zlib",
    "romeo.txt",
    "romeo.txt.deflate",
    "romeo.txt.fixed-huff.deflate",
    "romeo.txt.zlib",
];

/// `tests/data/wuffs-deflate-artificial/`: Wuffs' `test/data/artificial-deflate/`.
pub const FILES_ARTIFICIAL: &[&str] = &[
    "backref-crosses-blocks.deflate",
    "backref-crosses-blocks.deflate.decompressed",
    "degenerate-huffman-0-bit.deflate",
    "degenerate-huffman-0-bit.deflate.decompressed",
    "degenerate-huffman-1-bit.deflate",
    "degenerate-huffman-1-bit.deflate.decompressed",
    "distance-32768.deflate",
    "distance-32768.deflate.decompressed",
    "distance-code-31.deflate",
    "distance-code-31.deflate.decompressed",
    "huffman-primlen-9.deflate",
    "huffman-primlen-9.deflate.decompressed",
];

/// The files of the suite in `dir`, by its name.
fn files_of(name: &str) -> Result<&'static [&'static str], String> {
    match name {
        "wuffs-deflate" => Ok(FILES_MAIN),
        "wuffs-deflate-artificial" => Ok(FILES_ARTIFICIAL),
        _ => Err(format!("no DEFLATE list for suite {name:?}")),
    }
}

/// Check the suite in `dir` and write its table.
pub fn convert(dir: &Path) -> Result<String, String> {
    let name = dir
        .file_name()
        .and_then(|n| n.to_str())
        .ok_or_else(|| format!("{}: no directory name", dir.display()))?;
    let files = files_of(name)?;
    let source =
        std::fs::read_to_string(dir.join("SOURCE.md")).map_err(|e| format!("SOURCE.md: {e}"))?;
    let mut out = String::new();
    let _ = writeln!(
        out,
        "// Generated by `cargo xtask testdata` from `tests/data/{name}/` \
         (xtask/src/testdata/wuffs_deflate.rs). Do not edit.\n\
         \n\
         /// One vendored file, checked against `SOURCE.md` when generated.\n\
         pub struct Case {{\n    \
             /// The file's name in `tests/data/{name}/`.\n    \
             pub file: &'static str,\n    \
             /// Its SHA-256, as `SOURCE.md` lists it.\n    \
             pub sha256: &'static str,\n    \
             /// Its bytes.\n    \
             pub bytes: &'static [u8],\n\
         }}\n\
         \n\
         /// Every file of the suite.\n\
         pub const FILES: &[Case] = &["
    );
    for file in files {
        let bytes = std::fs::read(dir.join(file)).map_err(|e| format!("{file}: {e}"))?;
        let hash = to_hex(&Sha256::digest(&bytes));
        let listed = listed_hash(&source, file)?;
        if hash != listed {
            return Err(format!(
                "{file}: SHA-256 {hash} differs from SOURCE.md's {listed}"
            ));
        }
        let _ = writeln!(
            out,
            "    Case {{\n        \
                 file: {file:?},\n        \
                 sha256: {hash:?},\n        \
                 bytes: include_bytes!(\"../data/{name}/{file}\"),\n    \
             }},"
        );
    }
    out.push_str("];\n");
    Ok(out)
}
